const boot=`
const seed=${JSON.stringify({overview,thread})};window.fixture={...seed,requests:[]};
let open,changed;
const host={version:1,platform:'daemon',workspace:{id:'default',name:'P6 fixture',endpoint:location.origin,address:seed.overview.me.address,realm:'',state:'enrolled'},workspaces:null,skins:[],onSkinsChange(){return()=>{};},onOpen(fn){open=fn;},listen(fn){changed=fn;return()=>{};},stage:async()=>{throw Error('fixture accepts no files');},file:async()=>{throw Error('fixture contains no files');},api:async(p,body)=>{
fixture.requests.push({path:p,body});if(p.startsWith('/api/overview'))return structuredClone(fixture.overview);if(p.startsWith('/api/dm?'))return structuredClone(fixture.thread);
if(p.startsWith('/api/agents'))return {host:body?.host||new URL(p,location.origin).searchParams.get('host')||seed.overview.me.address,local:!p.includes('host='),agents:[],sessions:[]};
if(p==='/api/dm/agent/invite'){fixture.thread.agents[0].shared=body.share;changed?.({type:'change',seq:++fixture.overview.seq});return structuredClone(fixture.thread.agents[0]);}
if(p.includes('/groups/invitations'))return [];if(p.startsWith('/api/typing/status'))return {send:false,scopes:[]};if(p.includes('/topics'))return {topics:[],placements:[]};return {};
}};
const skin=new URL(location.href).searchParams.get('skin'),base='/assets/skins/'+skin+'/';
const manifest=await(await fetch(base+'skin.json')).json();
if(manifest.document){const css=new CSSStyleSheet();css.replaceSync(await(await fetch(base+manifest.document)).text());document.adoptedStyleSheets=[css];}
const shadow=document.querySelector('#skin').attachShadow({mode:'open'}),css=new CSSStyleSheet();css.replaceSync(await(await fetch(base+manifest.style)).text());shadow.adoptedStyleSheets=[css];
const skinRoot=document.createElement('div');skinRoot.className='skin-root';shadow.append(skinRoot);const module=await import(base+manifest.entry);await module.mount(skinRoot,host);
window.openGroup=()=>open(seed.thread.id,'conversation');window.ready=true;
`;
const server=http.createServer((req,res)=>{const u=new URL(req.url,'http://127.0.0.1');if(u.pathname==='/'){res.setHeader('Content-Type','text/html');res.end('<!doctype html><meta name="viewport" content="width=device-width,initial-scale=1"><style>body{margin:0}#skin{height:100dvh}</style><div id="skin"></div><script type="module" src="/boot.mjs"></script>');return;}if(u.pathname==='/boot.mjs'){res.setHeader('Content-Type','text/javascript');res.end(boot);return;}if(u.pathname.startsWith('/assets/')){const file=path.resolve(root,'.'+u.pathname.slice(7));if(file.startsWith(root+path.sep)&&fs.existsSync(file)&&fs.statSync(file).isFile()){res.setHeader('Content-Type',file.endsWith('.mjs')?'text/javascript':file.endsWith('.css')?'text/css':file.endsWith('.json')?'application/json':file.endsWith('.woff2')?'font/woff2':'application/octet-stream');res.end(fs.readFileSync(file));return;}}res.statusCode=404;res.end('fixture route missing');});
(async()=>{let browser;const errors=[],shots=[];try{await new Promise(r=>server.listen(0,'127.0.0.1',r));const origin='http://127.0.0.1:'+server.address().port;browser=await chromium.launch({headless:true,executablePath:process.env.AGENTNET_CHROMIUM||'/usr/bin/chromium'});
for(const skin of ['comic','classic','zoom'])for(const width of [1280,390]){const context=await browser.newContext({viewport:{width,height:900}});await context.route('**/*',r=>new URL(r.request().url()).origin===origin?r.continue():r.abort());const page=await context.newPage();page.on('pageerror',e=>errors.push(skin+': '+e.stack));page.setDefaultTimeout(10000);await page.goto(origin+'/?skin='+skin);await page.waitForFunction(()=>window.ready);await page.evaluate(()=>openGroup());
if(skin==='comic'){await page.getByText('Verified group answer',{exact:false}).waitFor().catch(async e=>{await page.screenshot({path:path.join(evidence,'debug-comic.png')});console.error(JSON.stringify({errors,text:await page.locator('body').innerText(),requests:await page.evaluate(()=>fixture.requests)}));throw e;});const panel=page.getByRole('button',{name:'In this chat',exact:true});if(!await page.getByRole('article',{name:'Your agent, member'}).isVisible()){if(await panel.isVisible())await panel.click();else await page.getByRole('button',{name:'amazon_team. Who’s in this chat',exact:true}).click();}await page.getByRole('article',{name:'Your agent, member'}).waitFor();}
else {if(skin==='classic')await page.locator('#agents .assistant-participant').filter({hasText:'Your agent'}).click();await page.locator('.agent-card').filter({hasText:'Your agent'}).waitFor();}
const cards=skin==='comic'?page.getByRole('article',{name:'Your agent, member'}):page.locator('.agent-card').filter({hasText:'Your agent'});const text=await cards.first().innerText();assert(!/GUEST|Laptop|laptop/i.test(text.replace('sergey/laptop','')),skin+' own group agent is a person-owned member');assert(/Sergey|you/i.test(text)&&/Vitalii/.test(text),skin+' names both inviters');assert(/can be asked|every member/i.test(text),skin+' card states it can be asked');assert(!/Nothing more can be asked/.test(text),skin+' no contradictory dismissal copy');
await page.evaluate(()=>Promise.all(document.querySelector('#skin').shadowRoot.querySelector('.skin-root').getAnimations({subtree:true}).filter(a=>a.effect.getComputedTiming().iterations!==Infinity).map(a=>a.finished.catch(()=>{}))));await cards.first().scrollIntoViewIfNeeded();
const overflow=await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth);assert(!overflow,skin+' '+width+' document overflow');await page.evaluate(()=>document.fonts.ready);const shot=path.join(evidence,skin+'-group-members-'+width+'.png');await page.screenshot({path:shot});shots.push(shot);
if(skin==='comic'){const close=page.getByRole('button',{name:/Close/}).last();if(await close.isVisible())await close.click();const bring=page.getByRole('button',{name:width===1280?'Bring in':'Bring someone in',exact:true});await bring.first().click();{await page.getByText('Already in this chat · share more messages',{exact:true}).first().waitFor();await page.getByRole('radio',{name:/Your agent/}).first().locator('..').click();await page.getByRole('button',{name:/Share more messages with/}).waitFor();await page.screenshot({path:path.join(evidence,skin+'-share-more-'+width+'.png')});}}
await context.close();}
assert.deepEqual(errors,[]);console.log(JSON.stringify({ok:true,checks:'P6 member cards, author/target, inviters, plain state, share-more, desktop/phone',shots}));}finally{if(browser)await browser.close();server.close();}})().catch(e=>{console.error(e);process.exitCode=1;});
